// Language: JavaScript (Node.js)
const fs = require('fs');

function solve() {
    // Read the two lines exactly: an empty string is an empty line, so do not trim the whole input.
    const lines = fs.readFileSync(0, 'utf-8').split('\n');
    const a = (lines[0] || '').replace(/\r$/, '');
    const b = (lines[1] || '').replace(/\r$/, '');

    // Write your solution here
}

solve();

