#include <string>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    string a, b;
    // An empty string is an empty line: getline leaves the string empty.
    getline(cin, a);
    getline(cin, b);
    if (!a.empty() && a.back() == '\r') a.pop_back();
    if (!b.empty() && b.back() == '\r') b.pop_back();

    // Write your solution here

    return 0;
}

